## Manifest 完整接口定义

以下 JSON 与插件包内实际 `manifest.json` 逐字段一致，覆盖插件身份、权限、配置、鉴权、参数、校验、创建、Agent、查询、取消、结果下载、响应和 Agent 响应映射。`documentation` 字段的值就是当前完整文档；为避免文档在自身内部无限递归，JSON 中仅用等义占位文本表示正文。

```json
{
  "apiVersion": "yingce.plugin/v2",
  "id": "kling-v4-official",
  "name": "Kling 4.0 Official API",
  "version": "1.2.0",
  "author": "Open AI Canvas contributors / 影策",
  "description": "Kling 4.0 Official API 独立请求协议插件。",
  "documentation": "<当前插件的完整 documentation，由 README.md 与 docs/interface.md 拼接而成；为避免 JSON 递归，此处不重复展开正文。>",
  "permissions": [
    "generation.run",
    "media.read"
  ],
  "configuration": {
    "fields": [
      {
        "name": "apiKey",
        "type": "secret",
        "label": "API Key",
        "required": true
      }
    ]
  },
  "contributes": {
    "providers": [
      {
        "id": "kling-v4-official",
        "label": "Kling 4.0 Official API",
        "capabilities": [
          "video"
        ],
        "scopes": [
          "admin.system-channel",
          "user.custom-channel",
          "canvas",
          "creation",
          "agent"
        ],
        "baseUrl": "",
        "requiresPublicMediaUrls": true,
        "detachedPolling": true,
        "auth": {
          "type": "bearer",
          "field": "apiKey"
        },
        "videoModes": {
          "kling-4.0": {
            "text_to_video": {
              "maxImages": 0,
              "inputRoles": [],
              "ratios": [
                "21:9",
                "16:9",
                "9:16",
                "1:1",
                "4:3",
                "3:4"
              ]
            },
            "image_to_video": {
              "maxImages": 10,
              "inputRoles": [
                "first_frame",
                "middle_frame",
                "last_frame"
              ],
              "ratios": []
            },
            "reference_to_video": {
              "maxImages": 10,
              "inputRoles": [
                "first_frame",
                "middle_frame",
                "last_frame",
                "refer_image",
                "feature_video",
                "base_video",
                "element",
                "voice"
              ],
              "ratios": [
                "21:9",
                "16:9",
                "9:16",
                "1:1",
