            }
          },
          "kling-4.0-flash": {
            "text_to_video": {
              "maxImages": 0,
              "inputRoles": [],
              "ratios": [
                "21:9",
                "16:9",
                "9:16",
                "1:1",
                "4:3",
                "3:4"
              ]
            },
            "image_to_video": {
              "maxImages": 1,
              "inputRoles": [
                "first_frame"
              ],
              "ratios": []
            },
            "reference_to_video": {
              "maxImages": 10,
              "inputRoles": [
                "first_frame",
                "refer_image",
                "feature_video",
                "base_video",
                "element"
              ],
              "ratios": [
                "21:9",
                "16:9",
                "9:16",
                "1:1",
                "4:3",
                "3:4",
                "adaptive"
              ]
            }
          }
        },
        "videoOutputs": {
          "kling-4.0": {
            "resolutions": [
              "720p",
              "1080p"
            ],
            "minSeconds": 3,
            "maxSeconds": 30,
            "generateAudio": false
          },
          "kling-4.0-flash": {
            "resolutions": [
              "720p"
            ],
            "minSeconds": 3,
            "maxSeconds": 20,
            "generateAudio": false
          }
        },
        "parameters": [
          {
            "name": "model",
            "type": "string",
            "required": true,
            "mapping": "URL path",
            "description": "kling-4.0 或 kling-4.0-flash。"
          },
          {
            "name": "operation",
            "type": "string",
            "required": false,
            "mapping": "endpoint",
            "description": "文生、图生、全能参考可显式选择。"
          },
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "prompt / contents[].text",
            "description": "英文与非英文按官方混合配额校验。"
          },
          {
            "name": "images",
            "type": "media[]",
            "required": false,
            "mapping": "contents",
            "description": "首帧、中间帧、尾帧、参考图。"
          },
          {
            "name": "videos",
            "type": "media[]",
            "required": false,
            "mapping": "contents",
            "description": "特征参考或待编辑视频。"
          },
          {
            "name": "duration",
            "type": "integer",
            "required": false,
            "mapping": "settings.duration",
            "description": "省略时上游从提示词或待编辑视频推断。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "required": false,
            "mapping": "settings.aspect_ratio",
            "description": "图生省略，文生六种固定比例，全能参考另支持 adaptive。"
          },
          {
            "name": "resolution",
            "type": "string",
            "required": false,
            "mapping": "settings.resolution",
            "description": "标准版支持 720p 与 1080p，Flash 仅支持 720p。"
          },
          {
            "name": "watermark",
            "type": "boolean",
            "required": false,
            "mapping": "options.watermark_info.enabled",
            "description": "请求并保存水印版本。"
          },
          {
            "name": "providerOptions",
            "type": "object",
            "required": false,
            "mapping": "contents / settings.audio",
            "description": "仅接受本插件声明的素材角色、ID、主体、音色与音频处理选项。"
          }
        ],
        "requestBindings": [
          {
            "name": "imageParts",
            "value": {
              "$map": {
                "from": {
                  "$sortByOrder": {
                    "$ref": "request.images"
                  }
                },
                "as": "media",
                "in": {
                  "type": {
                    "$coalesce": [
                      {
                        "$at": [
                          {
                            "$ref": "request.providerOptions.kling-v4-official.imageRoles"
                          },
                          {
                            "$ref": "mediaIndex"
                          }
                        ]
                      },
                      {
                        "$if": {
                          "condition": {
                            "$in": [
                              {
                                "$ref": "media.role"
                              },
                              [
                                "reference_image",
                                "refer_image"
                              ]
                            ]
                          },
                          "then": "refer_image",
                          "else": {
                            "$if": {
                              "condition": {
                                "$in": [
                                  {
                                    "$ref": "media.role"
                                  },
                                  [
                                    "",
                                    "reference"
                                  ]
                                ]
                              },
                              "then": {
                                "$if": {
                                  "condition": {
                                    "$and": [
                                      {
                                        "$eq": [
                                          {
                                            "$len": {
                                              "$sortByOrder": {
                                                "$ref": "request.images"
                                              }
                                            }
                                          },
                                          1
                                        ]
                                      },
                                      {
                                        "$ne": [
                                          {
                                            "$ref": "request.operation"
                                          },
                                          "reference_to_video"
                                        ]
                                      }
                                    ]
                                  },
                                  "then": "first_frame",
                                  "else": "refer_image"
                                }
                              },
                              "else": {
                                "$ref": "media.role"
                              }
                            }
                          }
                        }
                      }
                    ]
                  },
                  "url": {
                    "$ref": "media.url"
                  },
                  "id": {
                    "$coalesce": [
                      {
                        "$at": [
                          {
                            "$ref": "request.providerOptions.kling-v4-official.imageIds"
                          },
                          {
                            "$ref": "mediaIndex"
                          }
                        ]
                      },
                      {
                        "$concat": [
                          "Image",
                          {
                            "$add": [
                              {
                                "$ref": "mediaIndex"
                              },
                              1
                            ]
                          }
                        ]
                      }
                    ]
                  }
                }
              }
            }
          },
          {
            "name": "videoParts",
            "value": {
              "$map": {
                "from": {
                  "$sortByOrder": {
                    "$ref": "request.videos"
                  }
                },
                "as": "media",
                "in": {
                  "type": {
                    "$coalesce": [
                      {
                        "$at": [
                          {
                            "$ref": "request.providerOptions.kling-v4-official.videoRoles"
                          },
                          {
                            "$ref": "mediaIndex"
                          }
                        ]
                      },
                      {
                        "$if": {
                          "condition": {
                            "$in": [
                              {
                                "$ref": "media.role"
                              },
                              [
                                "",
                                "reference",
                                "reference_video"
                              ]
                            ]
                          },
                          "then": "feature_video",
                          "else": {
                            "$ref": "media.role"
                          }
