                  "url": {
                    "$ref": "media.url"
                  },
                  "id": {
                    "$coalesce": [
                      {
                        "$at": [
                          {
                            "$ref": "request.providerOptions.kling-v4-official.videoIds"
                          },
                          {
                            "$ref": "mediaIndex"
                          }
                        ]
                      },
                      {
                        "$concat": [
