                }
              }
            }
          },
          {
            "name": "videoElements",
            "value": {
              "$filter": {
                "from": {
                  "$ref": "request.providerOptions.kling-v4-official.elements"
                },
                "as": "element",
                "where": {
                  "$eq": [
                    {
                      "$ref": "element.elementType"
