                    "video_character_elements"
                  ]
                }
              }
            }
          },
          {
            "name": "parts",
            "value": {
              "$concatArrays": [
                {
                  "$concatArrays": [
                    {
                      "$filter": {
                        "from": {
                          "$ref": "bindings.imageParts"
                        },
                        "as": "part",
                        "where": {
                          "$eq": [
                            {
                              "$ref": "part.type"
                            },
                            "first_frame"
