                    {
                      "$filter": {
                        "from": {
                          "$ref": "bindings.imageParts"
                        },
                        "as": "part",
                        "where": {
                          "$in": [
                            {
                              "$ref": "part.type"
                            },
                            [
                              "middle_frame",
                              "refer_image"
                            ]
                          ]
                        }
                      }
                    },
                    {
                      "$filter": {
                        "from": {
                          "$ref": "bindings.imageParts"
                        },
                        "as": "part",
                        "where": {
                          "$eq": [
                            {
                              "$ref": "part.type"
                            },
                            "last_frame"
                          ]
                        }
                      }
                    }
                  ]
                },
                {
                  "$ref": "bindings.videoParts"
                },
                {
                  "$map": {
                    "from": {
                      "$ref": "request.providerOptions.kling-v4-official.elements"
                    },
                    "as": "element",
                    "in": {
                      "type": "element",
                      "element_id": {
                        "$ref": "element.element_id"
                      },
                      "id": {
                        "$ref": "element.id"
                      }
                    }
                  }
                },
                {
                  "$map": {
                    "from": {
                      "$ref": "request.providerOptions.kling-v4-official.voices"
                    },
                    "as": "voice",
                    "in": {
                      "type": "voice",
                      "voice_id": {
                        "$ref": "voice.voice_id"
                      },
                      "id": {
                        "$ref": "voice.id"
                      }
